const DollLayers={
 columns:[0,166,324,482,640,796,952,1108,1254],
 maleHair:['正面中分','正面蓬松短发','正面银灰中分','正面整齐刘海'],
 femaleHair:['正面双马尾','正面粉色长波浪','正面高马尾','正面长直发'],
 expressions:['平静','温柔微笑','开心','小小生气','惊讶','害羞'],
 clothes:['男生白衬衫','男生学院开衫','男生白衬衫','男生学院开衫','女生学院套装','女生粉色连衣裙','女生学院套装','女生粉色连衣裙'],
 defaults(id){const previous=living.avatars[id]||{},male=previous.cut==='suit'||id!=='me'&&roles.findIndex(r=>r.id===id)%2===1,index=referenceIndex(id,previous);return {body:male?0:1,hair:male?0:8,expression:0,clothing:index,tone:'natural',...previous.mix}},
 valid(a){return a&&[0,1].includes(a.body)&&Number.isInteger(a.hair)&&a.hair>=0&&a.hair<16&&Number.isInteger(a.expression)&&a.expression>=0&&a.expression<6&&Number.isInteger(a.clothing)&&a.clothing>=0&&a.clothing<8&&['natural','black','silver','rose'].includes(a.tone)},
 rect(row,col){const inset=row===1?8:0;return [this.columns[col]+inset,row===1?474:row===2?704:row===3?974:194,this.columns[col+1]-this.columns[col]-inset*2,row===1?182:row===2?258:row===3?262:84]},
 svg(rect,target,clip=''){const [sx,sy,sw,sh]=rect,[x,y,w,h]=target,key='layer'+crypto.randomUUID().replace(/-/g,'');return `<svg class="doll-part" style="width:${w}px;height:${h}px" x="${x}" y="${y}" width="${w}" height="${h}" viewBox="${sx} ${sy} ${sw} ${sh}" preserveAspectRatio="none" overflow="hidden"><defs><clipPath id="${key}"><rect x="${sx}" y="${sy}" width="${sw}" height="${sh}"/></clipPath></defs><g clip-path="url(#${key})"><image href="assets/character-layers-v15.webp" width="1254" height="1254"/></g></svg>`},
 part(a,field){const m=this.parts(a),r=field==='hair'?m.hair:field==='clothing'?m.clothes:field==='body'?[m.base[0],m.base[1],m.base[2],140]:m.face;return `<span class="doll-part-preview"><svg viewBox="0 0 200 200">${this.svg16(r,[(200-180*r[2]/Math.max(r[2],r[3]))/2,(200-180*r[3]/Math.max(r[2],r[3]))/2,180*r[2]/Math.max(r[2],r[3]),180*r[3]/Math.max(r[2],r[3])])}</svg></span>`},
 parts(a){const male=a.hair<8,style=a.hair%4,col=a.clothing%2+(a.clothing>=4?2:0);return {hair:[style*314+8,male?8:302,298,male?258:320],base:[a.body===0?85:398,936,149,318],clothes:[col*314+35,635,245,298],face:[a.expression===0?647:956,1030,290,160]}},
 render(a){const m=this.parts(a),uid='walk'+crypto.randomUUID().replace(/-/g,''),part=(r,t)=>this.svg16(r,t),hairTarget=a.hair<8?[6,9,188,166]:[0,8,200,270],clothing=part(m.clothes,[22,160,156,242]);return `<span class="chibi layered-character" role="img" aria-label="自由搭配：${a.hair<8?this.maleHair[a.hair%4]:this.femaleHair[(a.hair-8)%4]}、${this.expressions[a.expression]}、${this.clothes[a.clothing]}"><svg viewBox="0 0 200 410"><defs><clipPath id="${uid}top"><rect width="200" height="315"/></clipPath><clipPath id="${uid}left"><rect x="0" y="315" width="100" height="95"/></clipPath><clipPath id="${uid}right"><rect x="100" y="315" width="100" height="95"/></clipPath></defs>${part(m.hair,hairTarget)}${part(m.base,[50,35,100,365])}<g clip-path="url(#${uid}top)">${clothing}</g><g class="doll-leg-left"><g clip-path="url(#${uid}left)">${clothing}</g></g><g class="doll-leg-right"><g clip-path="url(#${uid}right)">${clothing}</g></g>${a.expression?'<ellipse cx="100" cy="125" rx="33" ry="25" fill="#ffe7db"/>'+part(m.face,[65,102,70,43]):''}<svg width="200" height="166" style="width:200px;height:166px" overflow="hidden"><g style="filter:${{natural:'none',black:'brightness(.6)',silver:'grayscale(1) brightness(1.6)',rose:'sepia(.25) hue-rotate(285deg)'}[a.tone]}">${part(m.hair,hairTarget)}</g></svg></svg></span>`},
 svg16(rect,target){const [sx,sy,sw,sh]=rect,[x,y,w,h]=target,k='p'+crypto.randomUUID().replace(/-/g,'');return `<svg x="${x}" y="${y}" width="${w}" height="${h}" style="width:${w}px;height:${h}px" viewBox="${sx} ${sy} ${sw} ${sh}" preserveAspectRatio="none" overflow="hidden"><defs><clipPath id="${k}"><rect x="${sx}" y="${sy}" width="${sw}" height="${sh}"/></clipPath></defs><g clip-path="url(#${k})"><image href="assets/character-parts-v16.webp" width="1254" height="1254"/></g></svg>`}

};
const referenceAvatarRenderer=chibiAvatar;
chibiAvatar=function(id='me',draft=null){const a=draft||living.avatars[id]||{},uploaded=!draft&&mediaCache.get('chibi:'+id);if(uploaded)return referenceAvatarRenderer(id);return DollLayers.render(a.layered&&DollLayers.valid(a.mix)?a.mix:DollLayers.defaults(id))};
const referenceOutfitEditor=openChibiEditor;
openChibiEditor=function(id='me'){let mix=DollLayers.defaults(id);const draw=()=>{const key=['rose','mint','lilac','gold'][mix.clothing%4],owned=homeland.owned.includes(key),price=PalaisHome.clothes[key].price;const choices=(label,field,items,offset=0)=>`<h3>${label}</h3><div class="doll-layer-choices">${items.map((name,i)=>`<button data-layer-field="${field}" data-layer-index="${i+offset}" aria-pressed="${mix[field]===i+offset}">${DollLayers.part({...mix,[field]:i+offset},field)}<small>${name}</small></button>`).join('')}</div>`;const d=homePanel(`<div class="eyebrow">MIX YOUR OWN LITTLE PERSON</div><h2>${id==='me'?'我':escapeHtml(roles.find(r=>r.id===id)?.name||'角色')} · 自由搭配</h2><div class="living-preview" id="chibiLive">${DollLayers.render(mix)}</div><p class="daily-caption">发型、表情和衣服是独立图层，选哪个就组合哪个。每位角色单独保存；预览免费，未拥有的衣服确认后才付钱。</p><div class="chibi-choices"><button data-layer-field="body" data-layer-index="0">${DollLayers.part({...mix,body:0},'body')}男生脸型</button><button data-layer-field="body" data-layer-index="1">${DollLayers.part({...mix,body:1},'body')}女生脸型</button></div>${choices('男生发型','hair',DollLayers.maleHair)}${choices('女生发型','hair',DollLayers.femaleHair,8)}<h3>发色色调（只改变头发）</h3><div class="chibi-choices">${[['natural','原色'],['black','深黑'],['silver','银灰'],['rose','雾玫瑰']].map(([v,n])=>`<button data-hair-tone="${v}" aria-pressed="${mix.tone===v}">${n}</button>`).join('')}</div>${choices('表情','expression',DollLayers.expressions.slice(0,2))}${choices('服装','clothing',DollLayers.clothes.slice(0,2))}${choices('女生服装','clothing',DollLayers.clothes.slice(4,6),4)}<p class="daily-caption">零钱 ¥${PalaisWallet.money(wallet.balance)} · 当前服装${owned?'已拥有':' ¥'+PalaisWallet.money(price*100)}</p><div class="actions"><button class="secondary" id="uploadLayeredFigure">上传完整形象</button><button class="primary" id="saveLayeredFigure">${owned?'保存搭配':'购买并保存 · ¥'+PalaisWallet.money(price*100)}</button></div><input type="file" hidden id="layeredFigureFile" accept="image/png,image/jpeg,image/webp">`);d.querySelectorAll('[data-layer-field]').forEach(b=>b.onclick=()=>{mix[b.dataset.layerField]=Number(b.dataset.layerIndex);draw()});d.querySelectorAll('[data-hair-tone]').forEach(b=>b.onclick=()=>{mix.tone=b.dataset.hairTone;draw()});$('#uploadLayeredFigure').onclick=()=>$('#layeredFigureFile').click();$('#layeredFigureFile').onchange=async e=>{try{await mediaWrite('chibi:'+id,await prepareImage(e.target.files[0],1000));d.close();renderHomeland();toast('完整形象已上传')}catch(e){toast(e.message)}};$('#saveLayeredFigure').onclick=async()=>{const b=$('#saveLayeredFigure');b.disabled=true;try{if(!DollLayers.valid(mix))throw Error('请选择有效的搭配');const chosen={...mix},purchaseKey=['rose','mint','lilac','gold'][chosen.clothing%4],result=PalaisHomeCash.purchaseStyle(wallet,homeland,purchaseKey,crypto.randomUUID(),Date.now(),PalaisHome.clothes),old=mediaCache.get('chibi:'+id)||null;await mediaWrite('chibi:'+id,null);try{livingCommit(result.wallet,{...living,avatars:{...living.avatars,[id]:{...living.avatars[id],layered:true,mix:chosen,outfit:purchaseKey}}},result.home)}catch(e){await mediaWrite('chibi:'+id,old).catch(()=>{});throw e}d.close();renderHomeland();toast('发型、表情与衣服的独立搭配已保存')}catch(e){toast(e.message);b.disabled=false}}};draw()};
